using Xunit;
using Moq;
using Microsoft.AspNetCore.Mvc;
using Api.Controllers;
using Api.Services;
using Api.Models;

public class ProductsControllerTests
{
    [Fact]
    public async Task GetById_WhenProductExists_ReturnsOkWithProduct()
    {
        // Arrange
        var productId = 42;
        var expectedProduct = new ProductDto
        {
            Id = productId,
            Name = "Wireless Headphones",
            Price = 79.99m
        };

        var mockService = new Mock<IProductService>();
        mockService
            .Setup(s => s.GetByIdAsync(productId))
            .ReturnsAsync(expectedProduct);

        var controller = new ProductsController(mockService.Object);

        // Act
        var result = await controller.GetById(productId);

        // Assert
        var okResult = Assert.IsType<OkObjectResult>(result.Result);
        var returnedProduct = Assert.IsType<ProductDto>(okResult.Value);
        Assert.Equal(productId, returnedProduct.Id);
        Assert.Equal("Wireless Headphones", returnedProduct.Name);
    }

    [Fact]
    public async Task GetById_WhenProductMissing_ReturnsNotFound()
    {
        // Arrange
        var mockService = new Mock<IProductService>();
        mockService
            .Setup(s => s.GetByIdAsync(It.IsAny<int>()))
            .ReturnsAsync((ProductDto?)null);

        var controller = new ProductsController(mockService.Object);

        // Act
        var result = await controller.GetById(999);

        // Assert
        Assert.IsType<NotFoundResult>(result.Result);
    }
}

