[Fact]
public async Task Delete_WhenCalled_CallsServiceWithCorrectId()
{
    // Arrange
    var mockService = new Mock<IProductService>();
    var controller = new ProductsController(mockService.Object);

    // Act
    var result = await controller.Delete(42);

    // Assert — verify the service was called exactly once with id=42
    mockService.Verify(
        s => s.DeleteAsync(42),
        Times.Once
    );

    // Also verify the result
    Assert.IsType<NoContentResult>(result);
}

[Fact]
public async Task Create_WithInvalidDto_ReturnsBadRequest()
{
    // Arrange
    var mockService = new Mock<IProductService>();
    var controller = new ProductsController(mockService.Object);

    // Create an invalid DTO (empty name fails [Required])
    var invalidDto = new CreateProductDto
    {
        Name = "",          // [Required] fails
        Price = -10,         // [Range] fails
        CategoryId = 0
    };

    // Act
    var result = await controller.Create(invalidDto);

    // Assert — [ApiController] returns 400 automatically
    var badRequest = Assert.IsType<BadRequestObjectResult>(result.Result);
    Assert.NotNull(badRequest.Value);

    // Verify the service was NEVER called because validation failed
    mockService.Verify(
        s => s.CreateAsync(It.IsAny<CreateProductDto>()),
        Times.Never
    );
}
